<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Factories\HasFactory; use Illuminate\Database\Eloquent\Model;
class FinancialActivity extends Model { use HasFactory; protected $fillable=['user_id','wallet_id','wallet_transaction_id','internal_transfer_id','reference','event_type','title','description','status','direction','amount','balance_before','balance_after','available_before','available_after','reserved_before','reserved_after','actor_type','actor_id','metadata']; protected $casts=['amount'=>'decimal:2','balance_before'=>'decimal:2','balance_after'=>'decimal:2','available_before'=>'decimal:2','available_after'=>'decimal:2','reserved_before'=>'decimal:2','reserved_after'=>'decimal:2','metadata'=>'array']; public function user(){return $this->belongsTo(User::class);} public function wallet(){return $this->belongsTo(Wallet::class);} public function walletTransaction(){return $this->belongsTo(WalletTransaction::class);} public function internalTransfer(){return $this->belongsTo(InternalTransfer::class);} public function actor(){return $this->belongsTo(User::class,'actor_id');} }
